def transpose(grid):
    """Rows and columns exchanged."""
    return [list(r) for r in zip(*grid)]

def rotate_cw(grid, k=1):
    """The grid rotated k quarter-turns clockwise."""
    for _ in range(k % 4):
        grid = transpose(vflip(grid))
    return grid

def rotate_ccw(grid, k=1):
    """The grid rotated k quarter-turns counterclockwise."""
    return rotate_cw(grid, 4 - (k % 4))

def rot180(grid):
    """The grid rotated two quarter-turns."""
    return vflip(hmirror(grid))

