def background(grid):
    """The most common color in the grid."""
    from collections import Counter
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def bbox(grid):
    """(top, left, bottom, right) of the non-background cells; None if none."""
    bg = background(grid)
    cells = [(i, j) for i, row in enumerate(grid) for j, v in enumerate(row) if v != bg]
    if not cells:
        return None
    return (min(i for i, _ in cells), min(j for _, j in cells),
            max(i for i, _ in cells), max(j for _, j in cells))

def outline_bbox(grid, color):
    """Draw color along the border of the non-background cells' bounding box, keeping the marked cells."""
    bg = background(grid)
    t, l, b, r = bbox(grid)
    out = [row[:] for row in grid]
    for j in range(l, r + 1):
        for i in (t, b):
            if out[i][j] == bg:
                out[i][j] = color
    for i in range(t, b + 1):
        for j in (l, r):
            if out[i][j] == bg:
                out[i][j] = color
    return out

