from collections import Counter

def background(grid):
    """The most common color in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def majority_color(grid, exclude=()):
    """The most common color excluding the given ones."""
    c = Counter(v for row in grid for v in row if v not in exclude)
    return c.most_common(1)[0][0]

def rare_color(grid, exclude=()):
    """The least common color excluding the given ones."""
    c = Counter(v for row in grid for v in row if v not in exclude)
    return min(c, key=c.get)

def bbox(grid):
    """(top, left, bottom, right) of the non-background cells; None if none."""
    bg = background(grid)
    cells = [(i, j) for i, row in enumerate(grid) for j, v in enumerate(row) if v != bg]
    if not cells:
        return None
    return (min(i for i, _ in cells), min(j for _, j in cells),
            max(i for i, _ in cells), max(j for _, j in cells))

def full_rows(grid, color):
    """Indices of rows that are entirely the given color."""
    return [i for i, row in enumerate(grid) if all(v == color for v in row)]

def full_cols(grid, color):
    """Indices of columns that are entirely the given color."""
    return [j for j in range(len(grid[0])) if all(row[j] == color for row in grid)]

def cells_of(grid, color):
    """Set of (row, col) of all cells of the given color."""
    return {(i, j) for i, row in enumerate(grid) for j, v in enumerate(row) if v == color}

def draw_line(out, idx, color, orient):
    """Draw a full row ('h') or column ('v') line at the given index on grid out."""
    if orient == 'h':
        out[idx] = [color] * len(out[idx])
    else:
        for row in out:
            row[idx] = color

def blit_color(out, cells, dr, dc, color):
    """Paint each (r, c) of cells shifted by (dr, dc) with color."""
    for r, c in cells:
        out[r + dr][c + dc] = color

def hmirror(grid):
    """The grid mirrored left to right."""
    return [row[::-1] for row in grid]

def vflip(grid):
    """The grid flipped top to bottom."""
    return grid[::-1]

def hstack(a, b):
    """The two grids side by side; they must have the same height."""
    return [ra + rb for ra, rb in zip(a, b)]

def vstack(*grids):
    """The grids stacked top to bottom; they must have the same width."""
    return [row for g in grids for row in g]

def draw_border(grid, color):
    """Color every background cell on the border of the non-background cells' bounding box, keeping marked cells."""
    bg = background(grid)
    t, l, b, r = bbox(grid)
    out = [row[:] for row in grid]
    for j in range(l, r + 1):
        for i in (t, b):
            if out[i][j] == bg:
                out[i][j] = color
    for i in range(t, b + 1):
        for j in (l, r):
            if out[i][j] == bg:
                out[i][j] = color
    return out

def fill_line_gaps(grid, color, continue_line=False):
    """Fill background cells sandwiched between two marked (non-background, non-color) cells in their row or column; with continue_line, only when the marked line continues on one side two cells away."""
    bg = background(grid)
    h, w = len(grid), len(grid[0])
    def mark(v):
        return v != bg and v != color
    out = [row[:] for row in grid]
    for i in range(h):
        for j in range(1, w - 1):
            a, m, c = out[i][j-1], out[i][j], out[i][j+1]
            if m == bg and mark(a) and mark(c) and (not continue_line or (j > 1 and mark(out[i][j-2])) or (j + 2 < w and mark(out[i][j+2]))):
                out[i][j] = color
    for j in range(w):
        for i in range(1, h - 1):
            a, m, c = out[i-1][j], out[i][j], out[i+1][j]
            if m == bg and mark(a) and mark(c) and (not continue_line or (i > 1 and mark(out[i-2][j])) or (i + 2 < h and mark(out[i+2][j]))):
                out[i][j] = color
    return out

def fill_h_gaps(grid, color=2):
    """Fill background cells that lie between a non-background cell on their left and one on their right in the same row."""
    bg = background(grid)
    out = [row[:] for row in grid]
    for row in out:
        for j, v in enumerate(row):
            if v == bg and any(x != bg for x in row[:j]) and any(x != bg for x in row[j+1:]):
                row[j] = color
    return out

def fall_down(grid):
    """The whole non-background content shifted down one row; whatever falls off the bottom is lost."""
    bg = background(grid)
    return [[bg] * len(grid[0])] + [row[:] for row in grid[:-1]]

def downsample_majority(grid, factor=None):
    """Each factor x factor block as its most common color that is neither 0 nor the background, or 0 if it has none; factor defaults to side // number of distinct colors."""
    h, w = len(grid), len(grid[0])
    if factor is None:
        factor = h // len({v for row in grid for v in row})
    bg = background(grid)
    out = []
    for k in range(0, h, factor):
        row = []
        for j in range(0, w, factor):
            cnt = Counter(v for r in grid[k:k+factor] for v in r[j:j+factor] if v != 0 and v != bg)
            row.append(cnt.most_common(1)[0][0] if cnt else 0)
        out.append(row)
    return out


def fill_ring_interiors(grid, color=None):
    """Fill the inside of every closed rectangular ring (hollow rectangle) with the given color."""
    bg = background(grid)
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if seen[i][j] or out[i][j] == bg:
                continue
            c = out[i][j]
            comp = [(i, j)]
            stack = [(i, j)]
            seen[i][j] = True
            while stack:
                r, cc = stack.pop()
                for nr, nc in ((r+1,cc),(r-1,cc),(r,cc+1),(r,cc-1)):
                    if 0 <= nr < h and 0 <= nc < w and not seen[nr][nc] and out[nr][nc] == c:
                        seen[nr][nc] = True
                        comp.append((nr, nc))
                        stack.append((nr, nc))
            rs = [r for r, _ in comp]; cs = [c2 for _, c2 in comp]
            t, l, b, r2 = min(rs), min(cs), max(rs), max(cs)
            if len(comp) == 2 * (b - t + 1) + 2 * (r2 - l + 1) - 4 and b > t + 1 and r2 > l + 1:
                area = (b - t - 1) * (r2 - l - 1)
                fillc = color if color is not None else (2 if area % 2 == 0 else 7)
                for m in range(t + 1, b):
                    for n in range(l + 1, r2):
                        out[m][n] = fillc
    return out

def extend_diagonal_runs(grid):
    """Complete every diagonal run of two or more same-colored cells whose diagonal also holds a different color: extend it through background cells to the border or the next cell."""
    bg = background(grid)
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for dr, dc in ((1, 1), (1, -1)):
        seen = set()
        for i in range(h):
            for j in range(w):
                if (i, j) in seen:
                    continue
                c = grid[i][j]
                if c == bg:
                    continue
                run = [(i, j)]; seen.add((i, j))
                y, x = i + dr, j + dc
                while 0 <= y < h and 0 <= x < w and grid[y][x] == c:
                    run.append((y, x)); seen.add((y, x)); y += dr; x += dc
                if len(run) < 2:
                    continue
                # does this diagonal contain a color other than c?
                other = False
                y, x = run[0][0] - dr, run[0][1] - dc
                while 0 <= y < h and 0 <= x < w:
                    if grid[y][x] != bg and grid[y][x] != c:
                        other = True
                    y -= dr; x -= dc
                y, x = run[-1][0] + dr, run[-1][1] + dc
                while 0 <= y < h and 0 <= x < w:
                    if grid[y][x] != bg and grid[y][x] != c:
                        other = True
                    y += dr; x += dc
                if not other:
                    continue
                for sy, sx, uy, ux in ((run[-1][0], run[-1][1], dr, dc), (run[0][0], run[0][1], -dr, -dc)):
                    y, x = sy + uy, sx + ux
                    while 0 <= y < h and 0 <= x < w and grid[y][x] == bg:
                        out[y][x] = c; y += uy; x += ux
    return out

def line_runs(cells):
    """Group cells into two parallel runs of >=2 sharing a row or column; returns (runs, horiz) or (None, None)."""
    from collections import defaultdict
    byrow=defaultdict(list); bycol=defaultdict(list)
    for i,j in cells: byrow[i].append(j); bycol[j].append(i)
    rr={i:sorted(v) for i,v in byrow.items() if len(v)>=2}
    cc={j:sorted(v) for j,v in bycol.items() if len(v)>=2}
    if len(rr)==2 and len(cc)!=2:
        return [[(i,j) for j in rr[i]] for i in sorted(rr)], True
    if len(cc)==2 and len(rr)!=2:
        return [[(i,j) for i in cc[j]] for j in sorted(cc)], False
    return None, None

def paired_beam_fill(grid, junction=4):
    """Two parallel marker runs and seed cells: each seed beams toward its run's cell (seed becomes `junction`),
    and the other run's cell at the same offset beams across the full line; both beams take the seed's color."""
    from collections import Counter
    h,w=len(grid),len(grid[0])
    cnt=Counter(v for r in grid for v in r)
    bg=cnt.most_common(1)[0][0]
    nonbg=[v for v,_ in cnt.most_common() if v!=bg]
    marker=None
    for v in nonbg:
        cells=[(i,j) for i in range(h) for j in range(w) if grid[i][j]==v]
        r,hz=line_runs(cells)
        if r: marker,R,horiz=v,r,hz
    seed=[v for v in nonbg if v!=marker][0]
    d1={k:c for k,c in enumerate(R[0])}; d2={k:c for k,c in enumerate(R[1])}
    out=[row[:] for row in grid]
    for (i,j) in [(i,j) for i in range(h) for j in range(w) if grid[i][j]==seed]:
        out[i][j]=junction
        for D,other in ((d1,d2),(d2,d1)):
            for k,(ri,rj) in D.items():
                if (horiz and j==rj) or (not horiz and i==ri):
                    oi,oj=other[k]
                    if horiz:
                        step=1 if ri>i else -1
                        for x in range(i+step,ri,step): out[x][j]=seed
                        for x in range(h):
                            if x!=oi: out[x][oj]=seed
                    else:
                        step=1 if rj>j else -1
                        for y in range(j+step,rj,step): out[i][y]=seed
                        for y in range(w):
                            if y!=oj: out[oi][y]=seed
                    break
            else: continue
            break
    return out


def stamp_marker_motif(grid, bg=None, noise=None, anchor=None):
    """Stamp the grid's small multi-color motif centered on every isolated noise dot."""
    from collections import Counter as _C
    bg = bg if bg is not None else background(grid)
    cnt = _C(v for r in grid for v in r)
    cands = [c for c in cnt if c != bg]
    noise = noise if noise is not None else max(cands, key=lambda c: cnt[c])
    ys = [y for y, r in enumerate(grid) for x, v in enumerate(r) if v not in (bg, noise)]
    xs = [x for y, r in enumerate(grid) for x, v in enumerate(r) if v not in (bg, noise)]
    y0, y1, x0, x1 = min(ys), max(ys), min(xs), max(xs)
    motif = [row[x0:x1 + 1] for row in grid[y0:y1 + 1]]
    H, W = len(motif), len(motif[0])
    ay, ax = anchor if anchor is not None else ((H - 1) // 2, (W - 1) // 2)
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for y in range(h):
        for x in range(w):
            if grid[y][x] == noise:
                for dy in range(H):
                    for dx in range(W):
                        yy, xx = y + dy - ay, x + dx - ax
                        if 0 <= yy < h and 0 <= xx < w:
                            out[yy][xx] = motif[dy][dx]
    return out


def concave_twin_recolor(grid, bg=None):
    """Recolor to the L-stroke color the shape-twin of the component nested in the L's concave corner."""
    bg = bg if bg is not None else background(grid)
    h, w = len(grid), len(grid[0])
    def comps(c):
        seen=set(); out=[]
        for i0 in range(h):
            for j0 in range(w):
                if grid[i0][j0]==c and (i0,j0) not in seen:
                    st=[(i0,j0)]; seen.add((i0,j0)); cl=set()
                    while st:
                        y,x=st.pop(); cl.add((y,x))
                        for ny,nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                            if 0<=ny<h and 0<=nx<w and grid[ny][nx]==c and (ny,nx) not in seen:
                                seen.add((ny,nx)); st.append((ny,nx))
                    out.append(cl)
        return out
    def norm(cl):
        ys=[y for y,x in cl]; xs=[x for y,x in cl]
        y0,x0=min(ys),min(xs)
        return frozenset((y-y0,x-x0) for y,x in cl)
    colors={v for row in grid for v in row}-{bg}
    cc={c:comps(c) for c in colors}
    out=[row[:] for row in grid]
    for dst in colors:
        for stroke in cc[dst]:
            ys=[y for y,x in stroke]; xs=[x for y,x in stroke]
            corners=[(y,x) for y,x in stroke
                     if sum(1 for yy,xx in stroke if xx==x)>=2 and sum(1 for yy,xx in stroke if yy==y)>=2
                     and {(yy,x) for yy,xx in stroke} | {(y,xx) for yy,xx in stroke} == stroke]
            if not corners: continue
            y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
            inside=[cl for c in colors-{dst} for cl in cc[c]
                    if all(y0<=y<=y1 and x0<=x<=x1 for y,x in cl) and not (cl & stroke)]
            if len(inside)!=1: continue
            inner=norm(inside[0])
            groups={}
            for c in colors-{dst}:
                for cl in cc[c]: groups.setdefault(norm(cl),[]).append(cl)
            for m in groups.get(inner,[]):
                if m is inside[0]: continue
                for y,x in m: out[y][x]=dst
    return out

def intersect_blocks(grid, color=2):
    """Cells non-zero in every patterned block, recolored; a single block maps to itself."""
    bl = [b for grp in pattern_blocks(grid, include_zero=True) for b in grp
          if any(len(set(row)) > 1 for row in b)]
    if len(bl) == 1:
        return [[color if v else 0 for v in row] for row in bl[0]]
    h, w = len(bl[0]), len(bl[0][0])
    return [[color if all(b[i][j] != 0 for b in bl) else 0 for j in range(w)] for i in range(h)]


def shared_color_mark(grid, mark=3):
    """The two blocks split by a full separator line, marked where both blocks show the color they share; that shared color elsewhere."""
    bl = [b for grp in pattern_blocks(grid, include_zero=True) for b in grp]
    A, B = bl[0], bl[1] if len(bl) > 1 else bl[0]
    shared = ({v for r in A for v in r} & {v for r in B for v in r}).pop()
    return [[mark if a == shared and b == shared else shared for a, b in zip(ra, rb)] for ra, rb in zip(A, B)]


def fill_between_walls(grid, wall, fill=3, only=None):
    """Cells (all non-wall cells, or just those of color `only`) with a wall both above and below in their column, or both left and right in their row, become `fill`."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for i in range(h):
        for j in range(w):
            if grid[i][j] == wall or (only is not None and grid[i][j] != only): continue
            colw = [r for r in range(h) if grid[r][j] == wall]
            roww = [c for c in range(w) if grid[i][c] == wall]
            if (any(r < i for r in colw) and any(r > i for r in colw)) or                (any(c < j for c in roww) and any(c > j for c in roww)):
                out[i][j] = fill
    return out


def diagonal_bands_tile(grid):
    """Colored diagonal lines (each a band of constant i-j or i+j) extend: the whole grid is tiled by those bands' colors cycling with period = number of colors."""
    cells=[(i,j,v) for i,row in enumerate(grid) for j,v in enumerate(row) if v]
    percolor=sum(1 for c in {v for _,_,v in cells} if len({i-j for i,j,v2 in cells if v2==c})==1)
    percolor2=sum(1 for c in {v for _,_,v in cells} if len({i+j for i,j,v2 in cells if v2==c})==1)
    band=(lambda i,j:i+j) if percolor2>=percolor else (lambda i,j:i-j)
    ds={band(i,j) for i,j,_ in cells}
    n=len(ds)
    m=next(m for m in range(2,30) if len({d%m for d in ds})==n)
    seq={}
    for i,j,v in cells: seq[band(i,j)%m]=v
    assert len(seq)==m
    return [[seq[band(i,j)%m] for j in range(len(grid[0]))] for i in range(len(grid))]


def fill_regions_with_pattern(grid):
    """Copy the one non-uniform region's content into every region of the grid, keeping the uniform separator lines."""
    b = background(grid)
    pat = None
    for r, c in regions_between_lines(grid):
        blk = [row[c[0]:c[1]] for row in grid[r[0]:r[1]]]
        if any(v != b for row in blk for v in row):
            pat = blk
    out = [row[:] for row in grid]
    for r, c in regions_between_lines(grid):
        for i, ri in enumerate(range(r[0], r[1])):
            out[ri][c[0]:c[1]] = pat[i]
    return out


def fill_rect_holes(grid, new=4, open_borders=('top', 'left', 'right', 'bottom')):
    """Fill every background region enclosed except via the given open borders, if it is a solid rectangle that is either fully walled or at least 2 columns wide, with color `new`."""
    h = len(grid)
    out = [row[:] for row in grid]
    for reg in enclosed_regions(grid, open_borders):
        walled = all(i != h - 1 for i, j in reg)
        wide = (max(j for i, j in reg) - min(j for i, j in reg) + 1) >= 2
        if is_solid_rect(reg) and (walled or wide):
            for i, j in reg:
                out[i][j] = new
    return out


def recolor_small_to_large_zero(grid):
    """The smaller of the grid's two colors becomes the larger, and the larger becomes 0."""
    vs = {v for row in grid for v in row}
    lo, hi = min(vs), max(vs)
    return [[hi if v == lo else (0 if v == hi else v) for v in row] for row in grid]


def fill_bounding_boxes(grid, min_size=4):
    """Keep large same-color components as solid rectangles: fill each component of at least min_size cells with its color over its bounding box, and turn every other non-background cell into the background color."""
    from collections import Counter
    bg = background(grid)
    h, w = len(grid), len(grid[0])
    out = [[bg] * w for _ in range(h)]
    fills = []
    for color in Counter(v for row in grid for v in row):
        if color == bg:
            continue
        for cells in components(grid, color):
            if len(cells) >= min_size:
                ys = [c[0] for c in cells]; xs = [c[1] for c in cells]
                fills.append((min(ys), min(xs), max(ys), max(xs), color))
    for y0, x0, y1, x1, color in fills:
        for i in range(y0, y1 + 1):
            for j in range(x0, x1 + 1):
                out[i][j] = color
    return out


def recolor_lines(grid, new, color=None):
    """Every cell in a single-color row or column (optionally of one given color) becomes `new`."""
    h, w = len(grid), len(grid[0])
    rows = {i for i, r in enumerate(grid) if len(set(r)) == 1 and (color is None or r[0] == color)}
    cols = {j for j in range(w) if len({r[j] for r in grid}) == 1 and (color is None or grid[0][j] == color)}
    return [[new if i in rows or j in cols else v for j, v in enumerate(r)] for i, r in enumerate(grid)]


def tile_rotations_quadrants(grid):
    """The grid tiled 2x2: top-left as-is, top-right rotated 90 clockwise, bottom-right 180, bottom-left 270."""
    n, w = len(grid), len(grid[0])
    tl = grid
    tr = rotate_cw(grid, 1)
    br = rot180(grid)
    bl = rotate_ccw(grid, 1)
    return vstack(hstack(tl, tr), hstack(bl, br))


def stamp_shape_on_fitting_spots(grid, color, bg=0):
    """Find the shape drawn in `color` and stamp copies everywhere it fits entirely on background cells."""
    H, W = len(grid), len(grid[0])
    cells = [(i, j) for i in range(H) for j in range(W) if grid[i][j] == color]
    if not cells:
        return [row[:] for row in grid]
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    shape = [(r - r0, c - c0) for r, c in cells]
    out = [row[:] for row in grid]
    for di in range(H):
        for dj in range(W):
            targets = [(di + sr, dj + sc) for sr, sc in shape]
            if all(0 <= i < H and 0 <= j < W and grid[i][j] == bg for i, j in targets):
                for i, j in targets:
                    out[i][j] = color
    return out


def corner_blocks(grid, fill=None):
    """Split the grid by rows/columns carrying rare marker colors; each lattice block gets color c if all 4 corner markers are c, else the fill color."""
    cnt = Counter(v for row in grid for v in row)
    if fill is None:
        fill = cnt.most_common(1)[0][0]
    keep = set(c for c, _ in cnt.most_common()[2:])
    mr = sorted({i for i, row in enumerate(grid) for j, v in enumerate(row) if v in keep})
    mc = sorted({j for row in grid for j, v in enumerate(row) if v in keep})
    out = []
    for a, b in zip(mr, mr[1:]):
        row = []
        for x, y in zip(mc, mc[1:]):
            cs = {grid[a][x], grid[a][y], grid[b][x], grid[b][y]}
            row.append(cs.pop() if len(cs) == 1 and cs <= keep else fill)
        out.append(row)
    return out


def complete_deficient_copy(grid, mark=1):
    """Copies of a multi-row pattern block (or left-anchored pattern bars): each deficient copy is completed from the most complete one, marking missing cells `mark`.

    For single-row pattern rows, every bar is completed rightward to the maximal bar extent.
    For two equal-height blocks, the horizontal shift dc is chosen by minimal contradiction
    (pattern cells of the deficient block not matching the shifted complete block), then maximal
    coverage; the deficient block's background cells under the shifted pattern become `mark`.
    """
    h, w = len(grid), len(grid[0])
    bg = background(grid)
    cnt = Counter(v for row in grid for v in row)
    pc = max((c for c in cnt if c not in (bg, mark)), key=lambda c: cnt[c])
    blocks = pattern_row_blocks(grid, bg, pc)
    out = [row[:] for row in grid]
    if all(len(b) == 1 for b in blocks):
        maxc = max(max(c for c in range(w) if grid[r][c] == pc) for r, in [(b[0],) for b in blocks])
        for r, in [(b[0],) for b in blocks]:
            for c in range(w):
                if grid[r][c] == bg and c <= maxc:
                    out[r][c] = mark
        return out
    def pc_count(bl): return sum(grid[r][c] == pc for r in bl for c in range(w))
    ref = max(blocks, key=pc_count)
    for bl in blocks:
        if bl == ref:
            continue
        best = None
        for dc in range(-w, w + 1):
            ex = cov = 0
            for i in range(len(bl)):
                er, br = grid[ref[i]], grid[bl[i]]
                for c in range(w):
                    sc = c - dc
                    if 0 <= sc < w:
                        if br[c] == pc and er[sc] != pc: ex += 1
                        if br[c] == pc and er[sc] == pc: cov += 1
            key = (ex, -cov, abs(dc))
            if best is None or key < best[0]:
                best = (key, dc)
        dc = best[1]
        for i in range(len(bl)):
            er, br = grid[ref[i]], grid[bl[i]]
            for c in range(w):
                sc = c - dc
                if br[c] == bg and 0 <= sc < w and er[sc] == pc:
                    out[bl[i]][c] = mark
    return out


def block_count_map(grid, color, include_zero=False):
    """Counts of color in each separator-delimited block, as a grid of counts."""
    return [[count_color(b, color) for b in row] for row in blocks(grid, include_zero)]


def l_stroke(grid, bg):
    """Find the L-shaped stroke (two perpendicular runs sharing a corner cell): (its color, its cells as a set)."""
    h, w = len(grid), len(grid[0])
    for c in {v for row in grid for v in row} - {bg}:
        cells = {(i, j) for i in range(h) for j in range(w) if grid[i][j] == c}
        if len(cells) < 3:
            continue
        ys = [y for y, x in cells]; xs = [x for y, x in cells]
        # an L: every cell on the bounding box edge rows/cols through the corner, no interior cells
        for cy, cx in cells:
            vert = {(y, cx) for y, x in cells}
            hor = {(cy, x) for y, x in cells}
            if (vert | hor) == cells and len(vert) >= 2 and len(hor) >= 2:
                return c, cells
    return None, set()


def pattern_blocks(grid, include_zero=False):
    """The patterned sub-blocks of the grid, split by uniform lines of separator colors (colors appearing only in uniform lines)."""
    ur, uc = uniform_lines(grid, include_zero)
    h, w = len(grid), len(grid[0])
    sep = {grid[i][0] for i in ur} | {grid[0][j] for j in uc}
    sep = {c for c in sep if all(i in ur or j in uc for i in range(h) for j in range(w) if grid[i][j] == c)}
    rows = [i for i in range(h) if not (i in ur and grid[i][0] in sep)]
    cols = [j for j in range(w) if not (j in uc and grid[0][j] in sep)]
    return [[[[grid[i][j] for j in c] for i in r] for c in index_runs(cols)] for r in index_runs(rows)]


def regions_between_lines(grid, rows=None, cols=None):
    """All (row-span, col-span) regions of the grid separated by its uniform non-background lines."""
    b = background(grid)
    ur, uc = uniform_lines(grid)
    rows = [i for i in ur if grid[i][0] != b] if rows is None else rows
    cols = [j for j in uc if grid[0][j] != b] if cols is None else cols
    return [(r, c) for r in spans(rows, len(grid)) for c in spans(cols, len(grid[0]))]


def enclosed_regions(grid, open_borders=('top', 'left', 'right', 'bottom')):
    """The connected regions of background cells that do not touch the given grid borders: lists of (row, col)."""
    bg = background(grid)
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] == bg and (i, j) not in seen:
                comp, stack = {(i, j)}, [(i, j)]
                seen.add((i, j))
                border = False
                while stack:
                    y, x = stack.pop()
                    if (y == 0 and 'top' in open_borders) or (y == h-1 and 'bottom' in open_borders) \
                       or (x == 0 and 'left' in open_borders) or (x == w-1 and 'right' in open_borders):
                        border = True
                    for ny, nx in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == bg and (ny, nx) not in seen:
                            seen.add((ny, nx))
                            comp.add((ny, nx))
                            stack.append((ny, nx))
                if not border:
                    out.append(comp)
    return out


def components(grid, color):
    """The 4-connected components of cells of the given color, as lists of (row, col)."""
    from collections import deque
    h, w = len(grid), len(grid[0]); seen = set(); out = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] == color and (i, j) not in seen:
                q = deque([(i, j)]); seen.add((i, j)); cells = []
                while q:
                    y, x = q.popleft(); cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny, nx) not in seen:
                            seen.add((ny, nx)); q.append((ny, nx))
                out.append(cells)
    return out


def rotate_cw(grid, k=1):
    """The grid rotated 90 degrees clockwise k times."""
    for _ in range(k % 4):
        grid = [list(r) for r in zip(*grid[::-1])]
    return grid


def pattern_row_blocks(g, bg, pc):
    """The contiguous blocks of rows that contain the pattern color pc (background bg)."""
    prows=[r for r in range(len(g)) if any(g[r][c]==pc for c in range(len(g[0])))]
    return index_runs(prows)


def one_color_lines(grid, axis=None):
    """Indices of rows (axis=0) or columns (axis=1) that are a single color throughout; both if axis is None."""
    h, w = len(grid), len(grid[0])
    rows = [i for i in range(h) if len(set(grid[i])) == 1]
    cols = [j for j in range(w) if len({grid[i][j] for i in range(h)}) == 1]
    return (rows, cols) if axis is None else (rows if axis == 0 else cols)


def uniform_lines(grid, include_zero=False):
    """Indices of the rows and columns that are uniform and non-zero (all uniform lines if include_zero)."""
    ur = {i for i, row in enumerate(grid) if len(set(row)) == 1 and (include_zero or row[0] != 0)}
    uc = {j for j in range(len(grid[0])) if len({r[j] for r in grid}) == 1 and (include_zero or grid[0][j] != 0)}
    return ur, uc


def is_solid_rect(reg):
    rs=[i for i,j in reg]; cs=[j for i,j in reg]
    return (max(rs)-min(rs)+1)*(max(cs)-min(cs)+1)==len(reg)


def rot180(grid):
    """The grid rotated 180 degrees."""
    return [r[::-1] for r in grid[::-1]]


def index_runs(idx):
    """A sorted index list as its contiguous runs."""
    out = []
    for i in idx:
        if out and i == out[-1][-1] + 1: out[-1].append(i)
        else: out.append([i])
    return out


def blocks(g, include_zero=False):
    # split by solid uniform rows and columns (nonzero unless include_zero)
    sr={i for i,row in enumerate(g) if len(set(row))==1 and (include_zero or row[0]!=0)}
    sc={j for j in range(len(g[0])) if len({r[j] for r in g})==1 and (include_zero or g[0][j]!=0)}
    rs=[i for i in range(len(g)) if i not in sr]; cs=[j for j in range(len(g[0])) if j not in sc]
    # contiguous runs
    def runs(idx):
        out=[]; 
        for i in idx:
            if out and i==out[-1][-1]+1: out[-1].append(i)
            else: out.append([i])
        return out
    rr, cc = runs(rs), runs(cs)
    return [[[[g[i][j] for j in c] for i in r] for c in cc] for r in rr]


def spans(seps, n):
    """The maximal [start, end) spans of 0..n separated by the sorted separator indices."""
    out, s = [], 0
    for x in sorted(seps) + [n]:
        if x > s:
            out.append((s, x))
        s = x + 1
    return out


def rotate_ccw(grid, k=1):
    """The grid rotated 90 degrees counter-clockwise k times."""
    return rotate_cw(grid, 4 - (k % 4) if k % 4 else 0) if k % 4 else [r[:] for r in grid]


def count_color(grid, color):
    """How many cells of the grid equal color."""
    return sum(v == color for row in grid for v in row)

def shift_down(grid, fill=None):
    """Shift every row down by one; the new top row is filled with the given (default most common) color, and the last row is dropped."""
    if fill is None: fill=Counter(v for row in grid for v in row).most_common(1)[0][0]
    return [[fill]*len(grid[0])]+grid[:-1]


def downscale_block(grid, block=3, bg=(0, 5)):
    """Each block x block cell replaced by the block's single non-background color, else 0 (majority-color downscale)."""
    h, w = len(grid)//block, len(grid[0])//block
    return [[next(iter(c)) if len(c := {grid[bi*block+r][bj*block+cc] for r in range(block) for cc in range(block)} - set(bg)) == 1 else 0
             for bj in range(w)] for bi in range(h)]


def recolor_full_lines(grid, color=2):
    """Every row and every column that is one solid color throughout is recolored to the given color."""
    h, w = len(grid), len(grid[0])
    fullrows = {i for i, row in enumerate(grid) if len(set(row)) == 1}
    fullcols = {j for j in range(w) if len({row[j] for row in grid}) == 1}
    return [[color if (i in fullrows or j in fullcols) else v for j, v in enumerate(row)] for i, row in enumerate(grid)]

def transpose(grid):
    """The grid with rows and columns exchanged."""
    return [list(r) for r in zip(*grid)]

def vflip(grid):
    """The grid mirrored top to bottom."""
    return grid[::-1]

def hflip(grid):
    """The grid mirrored left to right."""
    return [row[::-1] for row in grid]

def rot180(grid):
    """The grid rotated by 180 degrees."""
    return hflip(vflip(grid))

def quadrant_kaleidoscope(grid):
    """The 2n x 2n grid whose quadrants are the grid, the flipped transpose (both ways), and the 180-degree rotation."""
    t = transpose(grid)
    tr = hflip(t)
    bl = vflip(t)
    br = rot180(grid)
    return [a + b for a, b in zip(grid, tr)] + [a + b for a, b in zip(bl, br)]


def repeat_bands_vertically(grid):
    """Each colored single-row band repeats vertically with period = number of colored bands (row kept mod that period)."""
    bands = [(i, row[0]) for i, row in enumerate(grid) if len(set(row)) == 1 and row[0] != 0]
    p = len(bands)
    m = {i % p: c for i, c in bands}
    return [[m[j % p] for _ in range(len(grid[0]))] for j in range(len(grid))]


def binarize(grid, bg=None):
    """The grid with the most common color (or given bg) mapped to 1 and every other color to 0."""
    from collections import Counter
    if bg is None:
        bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    return [[1 if v == bg else 0 for v in row] for row in grid]


def pivot_map(grid, pivot, fill=0):
    """Cells of the pivot color take the value of the grid's other pivot-excluded color; every other color becomes fill."""
    others = sorted({v for row in grid for v in row} - {pivot})
    m = {pivot: others[0]}
    m.update({c: fill for c in others})
    return [[m[v] for v in row] for row in grid]


def fill_between_markers(grid, fill=3):
    """Cells strictly between consecutive non-background (marker) cells in each row and column become fill; other cells unchanged."""
    from collections import Counter
    h, w = len(grid), len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    others = [c for c in cnt if c != bg]
    if not others:
        return [row[:] for row in grid]
    marker = others[0]
    out = [row[:] for row in grid]
    for i in range(h):
        ms = [j for j in range(w) if grid[i][j] == marker]
        for a, b in zip(ms, ms[1:]):
            for j in range(a + 1, b): out[i][j] = fill
    for j in range(w):
        ms = [i for i in range(h) if grid[i][j] == marker]
        for a, b in zip(ms, ms[1:]):
            for i in range(a + 1, b): out[i][j] = fill
    return out


def period_phase_rows(grid):
    """Every row filled with the color of the colored row at the same phase mod the smallest period making colored rows distinct."""
    h = len(grid)
    colored = [(i, row[0]) for i, row in enumerate(grid) if row[0] != 0]
    p = next(p for p in range(1, h + 1) if len({i % p for i, _ in colored}) == len(colored))
    phase = {i % p: c for i, c in colored}
    return [[phase[i % p]] * len(grid[0]) for i in range(h)]


def components8(grid, color):
    """The 8-connected components of cells of the given color, as lists of (row, col)."""
    from collections import deque
    h, w = len(grid), len(grid[0]); seen = set(); out = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] == color and (i, j) not in seen:
                q = deque([(i, j)]); seen.add((i, j)); cells = []
                while q:
                    y, x = q.popleft(); cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny, nx) not in seen:
                                seen.add((ny, nx)); q.append((ny, nx))
                out.append(cells)
    return out


def wave_fill_right(grid, fill=1, bg=None, marker=None):
    """Zigzag wave of marker runs: merge components joined by one diagonal bg gap (dr=1, dc=2); each row whose rightmost marker column equals its component's max column fills bg cells to the right edge with `fill` -- solid if the marker extends left of the tip or the cell directly above the tip is a marker, else every other column."""
    from collections import Counter
    h, w = len(grid), len(grid[0])
    if bg is None:
        bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    if marker is None:
        marker = next(c for c in {v for row in grid for v in row} if c != bg)
    pts = {(i, j) for i in range(h) for j in range(w) if grid[i][j] == marker}
    parent = {p: p for p in pts}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]; x = parent[x]
        return x
    def uni(a, b):
        ra, rb = find(a), find(b)
        if ra != rb: parent[ra] = rb
    for i, j in pts:
        for di in (-1, 0, 1):
            for dj in (-1, 0, 1):
                if (i + di, j + dj) in pts: uni((i, j), (i + di, j + dj))
    for i, j in pts:  # knight bridges across one shared background gap (horizontal-dominant)
        for di, dj in ((1, 2), (1, -2), (-1, 2), (-1, -2)):
            if (i + di, j + dj) not in pts: continue
            bridged = False
            for a in range(min(i, i + di), max(i, i + di) + 1):
                for b in range(min(j, j + dj), max(j, j + dj) + 1):
                    if (a, b) in pts or not (0 <= a < h and 0 <= b < w): continue
                    if grid[a][b] == bg and max(abs(a - i), abs(b - j)) <= 1 and max(abs(a - i - di), abs(b - j - dj)) <= 1:
                        bridged = True
            if bridged: uni((i, j), (i + di, j + dj))
    comps = {}
    for p in pts: comps.setdefault(find(p), []).append(p)
    comp_of = {cell: root for root, cells in comps.items() for cell in cells}
    out = [row[:] for row in grid]
    for i in range(h):
        mc = max((j for j, v in enumerate(grid[i]) if v == marker), default=-1)
        if mc < 0 or mc == w - 1 or (i, mc) not in comp_of: continue
        comp = comps[comp_of[(i, mc)]]
        mr = max(j for _, j in comp)
        fire = mc == mr
        if not fire and mc == mr - 1:
            rstar = min(r for r, c2 in comp if c2 == mr)
            if i == rstar + 1 and grid[rstar][mr - 1] == bg: fire = True
        if not fire: continue
        solid = (mc > 0 and grid[i][mc - 1] == marker) or (i > 0 and grid[i - 1][mc] == marker)
        for c in range(mc + 1, w):
            if ((c - mc) % 2 == 0 or solid) and out[i][c] == bg: out[i][c] = fill
    return out


def fill_periodic_stripes(grid):
    """Fill the whole grid with the periodic stripe coloring implied by its nonzero cells: colors lie on parallel (main or anti) diagonals repeating with some period."""
    h, w = len(grid), len(grid[0])
    for key in (lambda i, j: j - i, lambda i, j: i + j):
        for p in range(1, w + 1):
            P, ok = {}, True
            for i in range(h):
                for j in range(w):
                    if grid[i][j]:
                        k = key(i, j) % p
                        if k in P and P[k] != grid[i][j]:
                            ok = False
                            break
                        P[k] = grid[i][j]
                if not ok:
                    break
            if ok and len(P) == p:
                return [[P[key(i, j) % p] for j in range(w)] for i in range(h)]
    return grid


def fill_box_interiors(grid, fill):
    """Fill the interior of every closed rectangle of a single frame color with fill."""
    from collections import Counter
    h, w = len(grid), len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    frame = next(c for c in cnt if c != bg)
    g = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if g[r][c] != frame: continue
            for rb in range(r + 1, h):
                for cb in range(c + 1, w):
                    if g[rb][c] == g[r][cb] == g[rb][cb] == frame                        and all(g[r][j] == frame and g[rb][j] == frame for j in range(c, cb + 1))                        and all(g[i][c] == frame and g[i][cb] == frame for i in range(r, rb + 1))                        and all(g[i][j] == bg for i in range(r + 1, rb) for j in range(c + 1, cb)):
                        for i in range(r + 1, rb):
                            for j in range(c + 1, cb):
                                g[i][j] = fill
    return g


def solid_lines(grid):
    """Indices of full rows and full columns that are one nonzero color throughout: ('r', i) / ('c', j)."""
    h, w = len(grid), len(grid[0])
    out = [('r', i) for i in range(h) if len(set(grid[i])) == 1 and grid[i][0] != 0]
    out += [('c', j) for j in range(w) if len({row[j] for row in grid}) == 1 and grid[0][j] != 0]
    return out

def overlap_half(grid, color=2):
    """Split the grid at the solid separator line that leaves two equal halves; cells nonzero in both halves become color."""
    for kind, k in solid_lines(grid):
        if kind == 'r':
            top, bot = grid[:k], grid[k + 1:]
            if len(top) == len(bot) and len(top) > 0:
                return [[color if a and b else 0 for a, b in zip(ra, rb)] for ra, rb in zip(top, bot)]
        else:
            left = [row[:k] for row in grid]
            right = [row[k + 1:] for row in grid]
            if len(left[0]) == len(right[0]) and len(left[0]) > 0:
                return [[color if a and b else 0 for a, b in zip(ra, rb)] for ra, rb in zip(left, right)]
    raise ValueError('no separating solid line')


def recolor_scatter_to_bg(grid):
    """Each cell of the scattered (minority) color takes the background (majority) color, and the background becomes 0."""
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    return [[0 if v == bg else bg for v in row] for row in grid]

def shift_colors_down(grid):
    """Sorted distinct colors shift down one rank: the smallest becomes 0, each other color becomes the next smaller one."""
    s = sorted({v for row in grid for v in row})
    m = {s[0]: 0}
    for k in range(1, len(s)):
        m[s[k]] = s[k-1]
    return [[m[v] for v in row] for row in grid]

def remap_min_to_zero(grid):
    """The grid with its smallest nonzero color mapped to 0 and the other colors shifted one rank down."""
    s = sorted({v for row in grid for v in row} - {0})
    if not s:
        return [row[:] for row in grid]
    m = {s[0]: 0}
    for k in range(1, len(s)):
        m[s[k]] = s[k-1]
    return [[m[v] for v in row] for row in grid]


def demote_minority(grid, base=5):
    """Color base (default 5) becomes the grid's other color, and that other color becomes 0."""
    other = next(k for k in {v for row in grid for v in row} if k != base)
    return [[other if v == base else 0 for v in row] for row in grid]

