from lib import background, block_stats, separator_lines

def transform(grid):
    """Per separator-delimited block: the background color if the block holds exactly one
    anomaly cell (a color that is neither background nor a separator line's color), else 1."""
    rows, cols = separator_lines(grid)
    sep = {grid[i][0] for i in rows} | {grid[0][j] for j in cols}
    def cell(cells, r, c):
        n = sum(v not in sep and v != background(grid) for v in cells)
        return background(grid) if n == 1 else 1
    return block_stats(grid, cell)

from lib import background_off_lines, block_stats, separator_lines

def transform(grid):
    """Per separator-delimited block: the block background (the grid's dominant non-separator
    color) if the block holds exactly one cell of any other color, else 1."""
    rows, cols = separator_lines(grid)
    sep = {grid[i][0] for i in rows} | {grid[0][j] for j in cols}
    bg = background_off_lines(grid, sep)
    def cell(cells, r, c):
        return bg if sum(v != bg for v in cells) == 1 else 1
    return block_stats(grid, cell)

