from lib import background_color, fill_rect_components

def transform(grid):
    """Fill the bounding box of every non-background component of >=2 cells; isolated single pixels become background."""
    h, w = len(grid), len(grid[0])
    bg = background_color(grid)
    g = [[bg] * w for _ in range(h)]
    for c in {v for row in grid for v in row} - {bg}:
        for comp in fill_rect_components(grid, c):
            ys = [p[0] for p in comp]; xs = [p[1] for p in comp]
            for i in range(min(ys), max(ys) + 1):
                for j in range(min(xs), max(xs) + 1):
                    g[i][j] = c
    return g

